-- matrix_excluded_check  (§1, printed p.1)
update public.fields set verification_status='verified_against_standard', verification_quote='No es aplicable al muestreo de estuarios o aguas costeras, ni para la toma de muestras microbiológicas. NOTA 1 Los procedimientos para la toma de muestras microbiológicas son proporcionados en ISO 19458[10]. Esta parte de NCh-ISO 5667 tampoco es aplicable al análisis de sedimentos, sólidos en suspensión o biota, ni a tramos embalsados de ríos o cursos de agua. Adicionalmente, tampoco es aplicable al muestreo pasivo de aguas superficiales (ver ISO 5667-23). — printed p.1', verification_note='md-verified 2026-09-09 (§1, printed p.1) [VA]', verified_at=now() where id='dc3f2e22-092d-45a8-98ef-dbe196720e1f' and verification_status not in ('verified_against_standard','corrected');

-- normative_references_consulted  (§2, printed p.1)
update public.fields set verification_status='verified_against_standard', verification_quote='Los documentos siguientes son indispensables para la aplicación de esta norma. Para referencias con fecha, sólo se aplica la edición citada. Para referencias sin fecha se aplica la última edición del documento referenciado (incluyendo cualquier enmienda). ISO 5667-1, Water quality - Sampling - Part 1: Guidance on the design of sampling programmes and sampling techniques. ISO 5667-3, Water quality - Sampling - Part 3: Preservation and handling of water samples. ISO 5667-11, Water quality - Sampling - Part 11: Guidance on sampling of groundwaters. ISO 5667-14, Water quality - Sampling - Part 14: Guidance on quality assurance and quality control of environmental water sampling and handling. ISO 6107-2:2006, Water quality - Vocabulary - Part 2. — printed p.1', verification_note='md-verified 2026-09-09 (§2, printed p.1) [VA] NOTE: clause 2 lists the normative references but prints NO obligation to attest that they were consulted; the block gate CR-002 rests on this boilerplate - see STAGED R-4.', verified_at=now() where id='f9cdb9b8-c119-49f8-bcd1-d4dbe5beb8fd' and verification_status not in ('verified_against_standard','corrected');

-- sampling_purpose  (Introducción, printed p.vi)
update public.fields set verification_status='verified_against_standard', verification_quote='La comprensión del propósito del muestreo es un prerrequisito fundamental para identificar los principios que se aplicarán a un problema de muestreo en particular. A continuación se encuentran ejemplos de los propósitos de los programas de muestreo comúnmente ideados para ríos y cursos de agua: a) determinar la idoneidad de la calidad del agua de un río o curso de agua dentro de una cuenca hidrográfica para un uso particular, como: | b) evaluar el impacto de las actividades humanas en la calidad del agua, como: — printed p.vi', verification_note='md-verified 2026-09-09 (Introducción, printed p.vi) [VA] NOTE: quote is from the Introduccion (printed p.vi), NOT from clause 1 as clause_reference says; the a/b list is printed as ''ejemplos'', so the 2-value enum closes an open example list - see STAGED R-6.', verified_at=now() where id='6ac8c9ec-e07b-4a5a-b8ca-0e030af1b1db' and verification_status not in ('verified_against_standard','corrected');

-- sampling_type  (§3, printed p.2-4)
update public.fields set verification_status='verified_against_standard', verification_quote='Para los propósitos de esta norma, se aplican los términos y definiciones incluidos en ISO 5667-11 e ISO 6107-2 y adicionalmente los siguientes: | muestreo automático proceso mediante el cual se toman las muestras, ya sea de forma discreta o continua, independientemente de la intervención humana y de acuerdo con un programa predeterminado | muestreo discreto proceso mediante el cual se toman muestras simples desde un cuerpo de agua | muestreo sistemático muestreo mediante el cual se toman las muestras a intervalos predeterminados, por lo general, igualmente espaciados en el tiempo — printed p.2-4', verification_note='md-verified 2026-09-09 (§3, printed p.2-4) [VA] NOTE: quote joins the clause-3 lead-in with three of the eight definitions the enum draws on (3.1, 3.4, 3.14); 3.2/3.3/3.5/3.6/3.8 are on printed pp.2-4 in the same list.', verified_at=now() where id='cc8bd60a-e3ee-4bb5-84f8-7cb783909cfd' and verification_status not in ('verified_against_standard','corrected');

