-- river_characteristics_recorded  (§4, printed p.5)
update public.fields set verification_status='verified_against_standard', verification_quote='Adicionalmente, muchas características pueden influenciar el comportamiento de los contaminantes en sistemas fluviales. La comprensión de la naturaleza de estas características es importante al momento | de planificar y llevar a cabo los programas de muestreo fluviales. Entre los factores importantes, se incluyen: la temperatura, turbidez, profundidad, velocidad, turbulencia, inclinación, los cambios en la dirección y en las secciones transversales, y la naturaleza del lecho del río. — printed p.5', verification_note='md-verified 2026-09-09 (§4, printed p.5) [VA]', verified_at=now() where id='a6a76b4b-7057-4e24-8dae-eead6d1e36e1' and verification_status not in ('verified_against_standard','corrected');

-- sampling_point_file_kept  (§4, printed p.5)
update public.fields set verification_status='verified_against_standard', verification_quote='Los asuntos funcionales del muestreo, como la accesibilidad, pueden hacer que el punto de muestreo ideal sea poco práctico. Es esencial que cualquier cambio en el punto de muestreo designado, por cualquier motivo, se discuta y acuerde con el creador del programa de muestreo. El resultado de las deliberaciones se debería registrar en un archivo de puntos de muestreo que contenga indicaciones para llegar al sitio de muestreo, la ubicación detallada del punto de muestreo, el método de muestreo y los detalles específicos (por ejemplo, claves necesarias, asuntos de salud y seguridad). Puede diferenciar entre los puntos de muestreo equivalentes que se pueden utilizar si, — printed p.5', verification_note='md-verified 2026-09-09 (§4, printed p.5) [VA]', verified_at=now() where id='3e6db79d-37c2-438c-8e7a-ef33fef739b4' and verification_status not in ('verified_against_standard','corrected');

-- tidal_influence_checked  (§5.1.2, printed p.7)
update public.fields set verification_status='verified_against_standard', verification_quote='La persona encargada del muestreo debería tener conocimiento de que en los cursos de agua cercanos a la costa, podría haber una influencia de las mareas en el flujo, la calidad y la capacidad de mezclado del cuerpo de agua. En los casos que corresponda, esto se debería considerar y la persona encargada | del muestreo debería tomar las mediciones del flujo y la profundidad del agua para proporcionar una indicación del estado de la marea. Por lo general, el muestreo en diferentes estados de la marea es necesario. — printed p.7', verification_note='md-verified 2026-09-09 (§5.1.2, printed p.7) [VA]', verified_at=now() where id='c3af776c-69d0-4103-9671-c72302089db1' and verification_status not in ('verified_against_standard','corrected');

-- homogeneity_status  (§5.1.4, printed p.9)
update public.fields set verification_status='verified_against_standard', verification_quote='Si existe alguna posibilidad de que haya una distribución no homogénea de los determinantes de interés en el sitio seleccionado, se deberían realizar pruebas experimentales sobre la naturaleza y magnitud de cualquier heterogeneidad en las tres dimensiones. Si dichas pruebas muestran que los determinantes están distribuidos homogéneamente, cualquier punto de muestreo es suficiente. De lo contrario, se debería buscar otro sitio en el que los determinantes estén distribuidos homogéneamente. — printed p.9', verification_note='md-verified 2026-09-09 (§5.1.4, printed p.9) [VA]', verified_at=now() where id='c24da9a7-5d50-4d79-8fb9-3bb66eec84e2' and verification_status not in ('verified_against_standard','corrected');

