update public.fields set verification_status='verified_against_standard', verification_quote='la cantidad de trabajo que esto implica. La parte de la sección transversal a través de la cual una gran parte (alrededor del 90%) de los pasos totales de flujo, se decide aproximadamente. Dentro de esa parte, se deberían tomar aproximadamente seis muestras repartidas a través de la parte. Los grandes ríos podrían requerir más muestras laterales y verticales. Para determinar si algunas diferencias — printed p.9', verification_note='md-verified 2026-09-09 (§5.1.4, printed p.9) [VA] NOTE: the printed figure is ''aproximadamente seis'' (approximately six); gate CR-008 enforces it as a hard floor >= 6 - see STAGED R-9.', verified_at=now() where id='283c1f5a-7a10-413a-bac0-4b34543c8f41' and verification_status not in ('verified_against_standard','corrected');

