-- mixing_dimension  (§5.1.2, printed p.6-7)
update public.fields set verification_status='verified_against_standard', verification_quote='En un curso de agua, los efluentes se mezclan en tres dimensiones, es decir, a) verticalmente (de arriba hacia abajo); b) lateralmente (de un lado al otro); y c) longitudinalmente (nivelando las máximas y mínimas en la concentración de los componentes del efluente, cuando el agua pasa aguas abajo). | Las distancias sobre las cuales los efluentes se mezclan en estas tres dimensiones, deberían ser consideradas en la selección de los sitios y puntos de muestreo, y son afectadas por, entre otros factores, la velocidad del agua. Las técnicas de trazadores que utilizan tintes pueden ser útiles en el estudio de — printed p.6-7', verification_note='md-verified 2026-09-09 (§5.1.2, printed p.6-7) [VA] NOTE: the source requires all THREE dimensions to be considered (''se mezclan en tres dimensiones ... deberian ser consideradas''); the field is a single-select enum - see STAGED R-8.', verified_at=now() where id='220c5dd9-68b4-48fb-8a15-cdb26097fc94' and verification_status not in ('verified_against_standard','corrected');

-- vertical_mixing_distance  (§5.1.2, printed p.7)
update public.fields set verification_status='verified_against_standard', verification_quote='La mezcla vertical, casi siempre, es el primero de los tres tipos en estar completo en un curso de agua. El agua poco profunda y las altas velocidades dan como resultado una mezcla vertical rápida, pero incluso en aguas profundas con bajas velocidades, la mezcla vertical es relativamente rápida. Los efluentes descargados a la mayoría de los cursos de agua se mezclan verticalmente, dentro de 100 m o dentro de unos pocos cientos de metros como máximo. Por lo tanto, normalmente no es necesario que un curso de agua se someta a muestras a más de una profundidad, aunque la estratificación — printed p.7', verification_note='md-verified 2026-09-09 (§5.1.2, printed p.7) [VA]', verified_at=now() where id='578291da-eebc-4819-a26b-11bd63686828' and verification_status not in ('verified_against_standard','corrected');

-- confluence_sites_count  (§5.1.2, printed p.6)
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando los efectos de un afluente o un efluente sobre la calidad en un particular tramo de río identificado, o el curso de agua principal son de interés, se deberían elegir al menos dos sitios de muestreo; uno debería estar justo aguas arriba de la confluencia y el otro debería estar lo suficientemente alejado aguas abajo para asegurar que la mezcla esté completa. — printed p.6', verification_note='md-verified 2026-09-09 (§5.1.2, printed p.6) [VA] NOTE: the obligation is CONDITIONAL (''Cuando los efectos de un afluente o un efluente ... son de interes''); gate CR-006 enforces >= 2 unconditionally - see STAGED R-5.', verified_at=now() where id='7be09e28-cd2f-44a6-b037-83a093271cb0' and verification_status not in ('verified_against_standard','corrected');

-- heterogeneity_determinant  (§5.1.4, printed p.10)
update public.fields set verification_status='verified_against_standard', verification_quote='Cabe señalar que diferentes determinantes pueden mostrar diferentes grados de heterogeneidad. Se sugiere que los siguientes determinantes (siempre que sean requeridos para el programa de rutina) deberían ser comprobados en cada ubicación de muestreo que se va a testear: pH, conductividad, cloro, amoníaco, sólidos en suspensión, oxígeno disuelto, color, hierro, clorofila, carbono orgánico total, y la demanda bioquímica de oxígeno. Se deberían incluir otros determinantes si son de interés especial o si son indicados por circunstancias locales. — printed p.10', verification_note='md-verified 2026-09-09 (§5.1.4, printed p.10) [VA] NOTE: the printed list is explicitly OPEN (''Se deberian incluir otros determinantes si son de interes especial''); the enum closes it at 11 - see STAGED R-8.', verified_at=now() where id='850878c4-2676-4e56-b51d-bc8f971d7a60' and verification_status not in ('verified_against_standard','corrected');

-- travel_time_required  (§5.1.3, printed p.8)
update public.fields set verification_status='verified_against_standard', verification_quote='El tiempo de viaje es el tiempo que tarda una determinada masa de agua en moverse entre dos puntos definidos. Esto puede ser desde un punto de descarga al siguiente punto de descarga, o desde un punto de descarga a un punto de extracción, etc. La información acerca del tiempo de viaje o la retención de sustancias del río en esta masa de agua, es importante por las razones principales siguientes: — printed p.8', verification_note='md-verified 2026-09-09 (§5.1.3, printed p.8) [VA]', verified_at=now() where id='500d71c2-6639-4012-aef7-50a5799af1bc' and verification_status not in ('verified_against_standard','corrected');

-- travel_time_method  (§5.1.3, printed p.8)
update public.fields set verification_status='verified_against_standard', verification_quote='Al determinar el tiempo de viaje, se debería utilizar uno de los tres métodos principales, específicamente el uso de flotadores de superficie (ver ISO 748), el uso de trazadores (ver ISO 9555), la medición del caudal con conocimiento de las áreas de sección transversal (ver ISO 748 e ISO 1070). — printed p.8', verification_note='md-verified 2026-09-09 (§5.1.3, printed p.8) [VA]', verified_at=now() where id='c1067a77-998b-43e6-a52a-ae1370a22396' and verification_status not in ('verified_against_standard','corrected');

-- travel_time_flows_count  (§5.1.3, printed p.9)
update public.fields set verification_status='verified_against_standard', verification_quote='Las mediciones se deberían realizar en un mínimo de cinco caudales diferentes y los tiempos de viaje resultantes trazados en relación con los caudales correspondientes, permitiendo así que se obtengan otros tiempos de viaje mediante la extrapolación o interpolación. Sin embargo, la — printed p.9', verification_note='md-verified 2026-09-09 (§5.1.3, printed p.9) [VA] NOTE: printed ''un minimo de cinco caudales diferentes'' - gate CR-009 (>= 5) matches; but CR-009''s scope predicate tests travel_time_method = '''' instead of travel_time_required - see STAGED R-14.', verified_at=now() where id='f6c98760-e60f-450e-9381-e91a80602147' and verification_status not in ('verified_against_standard','corrected');

-- travel_time_extrapolation_limit  (§5.1.3, printed p.9)
update public.fields set verification_status='verified_against_standard', verification_quote='se obtengan otros tiempos de viaje mediante la extrapolación o interpolación. Sin embargo, la extrapolación fuera del 10% de un valor de medición del caudal puede proporcionar información incorrecta sobre el tiempo de viaje. — printed p.9', verification_note='md-verified 2026-09-09 (§5.1.3, printed p.9) [VA] NOTE: printed with a permissive modality (''puede proporcionar informacion incorrecta''); correctly left un-gated.', verified_at=now() where id='4c2cb4da-f15b-4390-9dd6-cc862b3f9ff4' and verification_status not in ('verified_against_standard','corrected');

-- statistical_design_done  (§5.2, printed p.10)
update public.fields set verification_status='verified_against_standard', verification_quote='Es esencial que el programa de muestreo esté adecuadamente diseñado estadísticamente, con el fin de que la información estadística resumida producida a partir de los resultados analíticos, entregue una estimación de la información requerida dentro de los límites de tolerancia de los objetivos del | programa. Si los objetivos no incluyen una definición de la magnitud del error aceptable, no es posible un programa de muestreo basado en estadística. Implementar las orientaciones y recomendaciones sobre la aplicación de las estadísticas a la frecuencia del muestreo proporcionadas en ISO 5667-1. — printed p.10', verification_note='md-verified 2026-09-09 (§5.2, printed p.10) [VA]', verified_at=now() where id='3681f3df-b4a3-417b-bf2c-2c68dc3e206b' and verification_status not in ('verified_against_standard','corrected');

-- acceptable_error_defined  (§5.2, printed p.10)
update public.fields set verification_status='verified_against_standard', verification_quote='programa. Si los objetivos no incluyen una definición de la magnitud del error aceptable, no es posible un programa de muestreo basado en estadística. Implementar las orientaciones y recomendaciones — printed p.10', verification_note='md-verified 2026-09-09 (§5.2, printed p.10) [VA]', verified_at=now() where id='c5e82d5d-a5c5-4dd3-8c0e-3a74e495f71d' and verification_status not in ('verified_against_standard','corrected');

-- sampling_strategy  (§5.2, printed p.10)
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando las variaciones cíclicas u otras variaciones persistentes están presentes, se debería buscar una mejor precisión en la estimación de las concentraciones medias por medio del muestreo sistemático en lugar del aleatorio (para cualquier cantidad dada de muestras), siempre que el intervalo del muestreo sea lo suficientemente corto como para que las muestras consecutivas revelen las variaciones. — printed p.10', verification_note='md-verified 2026-09-09 (§5.2, printed p.10) [VA]', verified_at=now() where id='38adf693-d4dd-4a64-ae4c-418d47d5149e' and verification_status not in ('verified_against_standard','corrected');

-- cycle_coincidence_avoided  (§5.2, printed p.10)
update public.fields set verification_status='verified_against_standard', verification_quote='Al utilizar el muestreo sistemático, se debe asegurar que la frecuencia del muestreo no coincida con ningún ciclo natural presente en el sistema o con algún otro efecto basado en el tiempo | (por ejemplo, una bomba justo aguas arriba comenzando una vez cada hora), un estudio de los efectos de los que no forman parte de los objetivos del muestreo. — printed p.10', verification_note='md-verified 2026-09-09 (§5.2, printed p.10) [VA] NOTE: printed ''se debe asegurar'' - a genuine shall; block gate CR-011 correctly rests on it.', verified_at=now() where id='0d7ce671-061c-4eca-8705-ed234efb3b69' and verification_status not in ('verified_against_standard','corrected');

-- trend_detection_design  (§5.2, printed p.10)
update public.fields set verification_status='verified_against_standard', verification_quote='Si el programa de muestreo está diseñado para detectar tendencias en la calidad del agua, se debería tener precaución durante su diseño, con el fin de garantizar que todas las variaciones de interés sean detectadas. Estos estudios temporales muestran los cambios en las condiciones físicas y/o químicas del río o curso de agua, debido a la contaminación o a la variación natural con el paso del tiempo. Los estudios se deberían llevar a cabo mediante el uso de puntos de muestreo fijos y metodologías estandarizadas de acuerdo con un programa establecido. Esto podría requerir que se tomen muestras a la misma hora, el mismo día o en el mismo mes, dependiendo de la posible duración y del flujo constante de la tendencia que se investigue. — printed p.10', verification_note='md-verified 2026-09-09 (§5.2, printed p.10) [VA]', verified_at=now() where id='f0e6c458-b4e5-4cad-92e1-a441036b031d' and verification_status not in ('verified_against_standard','corrected');

-- personnel_trained  (§6, printed p.11)
update public.fields set verification_status='verified_against_standard', verification_quote='A menudo, el muestreo de los ríos implica el trabajo en zonas relativamente alejadas durante la mayor parte del día, sin embargo, se debería evitar en lo posible el trabajo solitario, prefiriendo el trabajo en equipo, aunque a un costo mayor. Como resultado, los operadores de muestreo y los vehículos deberían ser autónomos y todo el personal de muestreo debería estar debidamente capacitado, además deberían recibir instrucciones claras del muestreo. Estas instrucciones pueden estar por — printed p.11', verification_note='md-verified 2026-09-09 (§6, printed p.11) [VA]', verified_at=now() where id='1df385b0-9f90-44b0-97c7-3e9c514685dd' and verification_status not in ('verified_against_standard','corrected');

-- sampling_folder_complete  (§6, printed p.11)
update public.fields set verification_status='verified_against_standard', verification_quote='La información siguiente debería estar disponible, como mínimo: a) una descripción precisa y la documentación del punto de muestreo; b) el tipo de muestra requerida; c) los protocolos y técnicas de muestreo aplicables; d) la información, si es necesaria, acerca de cualquier submuestra, por ejemplo, botellas, filtración, | preservación, o cualquier medición de campo, etc.; e) el orden de los recipientes de llenado, que puede ser importante en algunas condiciones, por ejemplo, para minimizar la contaminación. — printed p.11', verification_note='md-verified 2026-09-09 (§6, printed p.11) [VA]', verified_at=now() where id='6207e3f3-29b8-425a-819b-9fcc73bde052' and verification_status not in ('verified_against_standard','corrected');

-- transport_temperature  (§6, printed p.11)
update public.fields set verification_status='verified_against_standard', verification_quote='Muchas de las consideraciones tomadas en cuenta para almacenar el equipamiento en el depósito, se aplican al vehículo de muestreo (ver 11.2). En el vehículo, debería estar disponible un dispositivo de enfriamiento capaz de mantener las muestras a una temperatura de (5 ± 3)°C para el transporte. — printed p.11', verification_note='md-verified 2026-09-09 (§6, printed p.11) [VA] NOTE: the printed value is ''(5 +/- 3) degC''; gate CR-014''s 2..8 degC window is the arithmetic expansion of that tolerance, inclusive on both ends - matches the print.', verified_at=now() where id='0542c16a-e322-4903-9009-8c23590979bd' and verification_status not in ('verified_against_standard','corrected');

-- vehicle_racking_used  (§6, printed p.11)
update public.fields set verification_status='verified_against_standard', verification_quote='Precauciones para el transporte: el vehículo debería estar equipado con estantería para sostener el equipamiento y evitar cualquier movimiento que pueda causar una rotura. Esto es especialmente importante para las botellas de vidrio, botellas con conservantes y medidores manuales. — printed p.11', verification_note='md-verified 2026-09-09 (§6, printed p.11) [VA]', verified_at=now() where id='4b02c8a0-d6d0-4283-8ff9-09cb2861a7fd' and verification_status not in ('verified_against_standard','corrected');

-- sampling_location_type  (§7, printed p.12-16)
update public.fields set verification_status='verified_against_standard', verification_quote='7 Muestreo en ubicaciones específicas | 7.2 Toma de muestras desde puentes | 7.3 Muestreo en el curso de agua | 7.4 Muestreo desde la orilla | 7.5 Muestreo desde embarcaciones | 7.6 Muestreo bajo hielo — printed p.12-16', verification_note='md-verified 2026-09-09 (§7, printed p.12-16) [VA] NOTE: quote joins the clause-7 heading with the five sub-clause headings the enum mirrors 1:1.', verified_at=now() where id='e4987062-65c4-4fa0-8fda-2e574bd6952f' and verification_status not in ('verified_against_standard','corrected');

-- bridge_position  (§7.2, printed p.13-14)
update public.fields set verification_status='verified_against_standard', verification_quote='Los recipientes de recolección se deberían sumergir en el flujo principal del cauce del río, de preferencia, aguas arriba del puente. | En Tabla 1 se listan las ventajas y desventajas de recolectar muestras aguas arriba o debajo de un puente. | Tabla 1 – Ventajas y desventajas de la toma de muestras aguas arriba o debajo de un puente — printed p.13-14', verification_note='md-verified 2026-09-09 (§7.2, printed p.13-14) [VA]', verified_at=now() where id='3df8710b-9116-45c6-944b-bb850acab0a2' and verification_status not in ('verified_against_standard','corrected');

-- bridge_checks_passed  (§7.2, printed p.13)
update public.fields set verification_status='verified_against_standard', verification_quote='Al seleccionar el lugar en un puente del cual tomar la muestra, se debe asegurar que: a) exista la profundidad de agua suficiente para sumergir el recipiente de muestreo; b) cuando esté sumergido, el recipiente no perturbe los depósitos del fondo; c) haya suficiente claridad en el puente cuando se suspenda el recipiente para evitar que se desprenda, posiblemente contaminando el material de la estructura del puente; y d) al momento de tomar la muestra en el lado aguas arriba del puente, el operador de muestreo no quede sin visión, es decir, el recipiente no sea llevado bajo el puente por la corriente. — printed p.13', verification_note='md-verified 2026-09-09 (§7.2, printed p.13) [VA] NOTE: one of only ten ''debe'' (shall) obligations in the whole document, and block gate CR-015 correctly rests on it - yet the field itself is is_required=false - see STAGED R-15.', verified_at=now() where id='14030e31-9532-46bc-bb51-5fe2c206e25d' and verification_status not in ('verified_against_standard','corrected');

-- sampling_depth_below_surface  (§7.3, printed p.15)
update public.fields set verification_status='verified_against_standard', verification_quote='Los recipientes de recolección deberían ser sumergidos en el flujo principal del cauce del agua y en la zona homogénea, de manera tal de recoger una muestra de agua sin incluir la película superficial o remolinos de agua. Siempre que sea posible, las muestras de agua se deberían recoger a alrededor de 30 cm por debajo de la superficie, o de otra manera, a media altura entre el lecho y la superficie. — printed p.15', verification_note='md-verified 2026-09-09 (§7.3, printed p.15) [VA] NOTE: printed as ''alrededor de 30 cm'' (about 30 cm) under ''Siempre que sea posible''; no gate enforces it, which matches the soft modality.', verified_at=now() where id='bd3e0ab5-b323-426e-8f18-23394c7f2e4c' and verification_status not in ('verified_against_standard','corrected');

-- height_above_bed  (§7.1, printed p.13)
update public.fields set verification_status='verified_against_standard', verification_quote='Generalmente, se debería evitar el muestreo en o cerca de la superficie, en el fondo, en la orilla, en áreas estancadas y estanques. Es necesario tener especial precaución de no perturbar los sedimentos del fondo y evitar películas no representativas en la superficie. Siempre que sea posible, las muestras obtenidas de posiciones al menos 30 cm por encima del fondo de un curso de agua y a una distancia similar debajo de la superficie, suelen ser satisfactorias. — printed p.13', verification_note='md-verified 2026-09-09 (§7.1, printed p.13) [VA] NOTE: printed ''al menos 30 cm por encima del fondo'' - gate CR-016 (>= 30) matches the printed floor and its inclusivity.', verified_at=now() where id='a2f01b0e-6230-4591-a234-d364803579fd' and verification_status not in ('verified_against_standard','corrected');

-- ppe_high_visibility  (§7.1, printed p.13)
update public.fields set verification_status='verified_against_standard', verification_quote='Ver cláusula 15 acerca de las precauciones de seguridad y salud que se tomen para garantizar la seguridad de la persona encargada de extraer las muestras; sin embargo, se debería utilizar el equipamiento de protección personal (como el uso de chaquetas de alta visibilidad) y equipo de flotación (chalecos salvavidas) si es apropiado. — printed p.13', verification_note='md-verified 2026-09-09 (§7.1, printed p.13) [VA]', verified_at=now() where id='45813080-6843-490a-a766-74425a908dbf' and verification_status not in ('verified_against_standard','corrected');

-- preferred_subsurface_depth  (§7.3, printed p.15)
update public.fields set verification_status='verified_against_standard', verification_quote='remolinos de agua. Siempre que sea posible, las muestras de agua se deberían recoger a alrededor de 30 cm por debajo de la superficie, o de otra manera, a media altura entre el lecho y la superficie. — printed p.15', verification_note='md-verified 2026-09-09 (§7.3, printed p.15) [VA] NOTE: this field duplicates sampling_depth_below_surface (same clause, same value, same unit); the two are joined only by the pass-through Eq.2 - see STAGED R-10.', verified_at=now() where id='fa45871c-b23e-4a88-bbfd-92ca49e08474' and verification_status not in ('verified_against_standard','corrected');

-- sampling_method  (§8, printed p.16)
update public.fields set verification_status='verified_against_standard', verification_quote='8 Métodos de muestreo 8.1 Muestras discretas simples | En casos en los que el muestreo subterráneo (por ejemplo, dentro de 30 cm de la superficie del agua) sea aceptable, a menudo basta con sumergir un recipiente limpio (por ejemplo, un balde o una lata) en el río o curso de agua de interés. Los contenidos luego son vertidos en botellas de muestreo | 8.2 Muestreo desde profundidades específicas Cuando se requiere una muestra desde una profundidad específica, se debería utilizar equipamiento — printed p.16', verification_note='md-verified 2026-09-09 (§8, printed p.16) [VA]', verified_at=now() where id='57cab2e1-77d8-4259-81b1-b08c72b1055a' and verification_status not in ('verified_against_standard','corrected');

-- bottle_volume  (§9.1, printed p.17)
update public.fields set verification_status='verified_against_standard', verification_quote='Para facilitar la recolección de muestras, se debería emplear un rango de frascos de muestreo desde | 50 ml a 3 L. Con el fin de lograr los límites analíticos de detección que a menudo se requieren para los ríos limpios, incluso podrían ser necesarios grandes volúmenes de muestra, por lo tanto, podrían surgir problemas físicos de manipulación. — printed p.17', verification_note='md-verified 2026-09-09 (§9.1, printed p.17) [VA] NOTE: printed as a RANGE (50 ml to 3 L) under ''se deberia emplear''; the point value is an SR-2 engineer selection and no gate encodes the range.', verified_at=now() where id='097c7f4e-b0c3-4c98-b6e1-ee0f26ddf057' and verification_status not in ('verified_against_standard','corrected');

-- inlet_velocity  (§8.2, printed p.16)
update public.fields set verification_status='verified_against_standard', verification_quote='muchos dispositivos automáticos de muestreo. Idealmente, el muestreo se debería llevar a cabo en condiciones isocinéticas, pero cuando esto no es posible, la velocidad de flujo lineal dentro del tubo de entrada no debería ser menor que 0,5 m/s ni mayor que 3,0 m/s. — printed p.16', verification_note='md-verified 2026-09-09 (§8.2, printed p.16) [VA] NOTE: the printed modality is ''no deberia ser menor ... ni mayor'' (SHOULD); the field description says ''shall''. Values 0,5 / 3,0 m/s and the inclusive two-sided gate CR-017 match the print - see STAGED R-11.', verified_at=now() where id='694593a2-278b-4a22-a291-4d4a5843de14' and verification_status not in ('verified_against_standard','corrected');

-- isokinetic_conditions  (§8.2, printed p.17)
update public.fields set verification_status='verified_against_standard', verification_quote='Para el muestreo representativo de materiales insolubles, la velocidad del muestreo se debería ajustar, de modo que la velocidad del agua en la entrada del sistema de muestreo sea la misma a la del agua que se está muestreando (es decir, el muestreo se debería llevar a cabo bajo condiciones de muestreo isocinéticas). Esto también requiere que la entrada del sistema de muestreo esté de frente a la dirección del río o curso de agua. — printed p.17', verification_note='md-verified 2026-09-09 (§8.2, printed p.17) [VA]', verified_at=now() where id='7b8089e8-2fc6-4e77-ae6b-55a5a3c7fc73' and verification_status not in ('verified_against_standard','corrected');

-- equipment_inert_tested  (§9.1, printed p.17)
update public.fields set verification_status='verified_against_standard', verification_quote='Todo el equipamiento y los dispositivos se deberían componer, en lo posible, de materiales que sean inertes con respecto al (los) componente(s) a analizar. Antes de que se utilice cualquier equipamiento de muestreo, se deberían realizar pruebas para demostrar que su uso no tiene ningún efecto sobre el — printed p.17', verification_note='md-verified 2026-09-09 (§9.1, printed p.17) [VA]', verified_at=now() where id='c674419b-2aaa-46bc-80e2-92a61c457aae' and verification_status not in ('verified_against_standard','corrected');

-- automatic_sampler_mode  (§9.4, printed p.18)
update public.fields set verification_status='verified_against_standard', verification_quote='Los dispositivos automáticos simples se pueden programar para tomar muestras en intervalos de tiempo preestablecidos, o ser operados mediante un activador externo, como una señal generada por lluvias excesivas. Los dispositivos proporcionales al flujo más refinados, miden continuamente el flujo en el río o curso de agua y toma muestras luego de que un volumen fijo de agua ha pasado el punto de muestreo. — printed p.18', verification_note='md-verified 2026-09-09 (§9.4, printed p.18) [VA]', verified_at=now() where id='607cb886-c2a3-4ff0-a4c1-1dc9b8afe7e8' and verification_status not in ('verified_against_standard','corrected');

-- equipment_washes  (§10.3, printed p.20)
update public.fields set verification_status='verified_against_standard', verification_quote='Todo el equipamiento que entra en contacto con el agua, se debería lavar, preferiblemente, hasta tres veces. Tomar el volumen suficiente del cuerpo de agua del que se va a tomar una muestra para un lavado minucioso de todo el equipo, utilizando la técnica de muestreo que se utiliza en la zona. | Seguir las instrucciones que se encuentran en ISO 5667-3 para enjuagar botellas de muestreo. Es importante que las botellas de muestra no se enjuaguen si contienen conservantes. — printed p.20', verification_note='md-verified 2026-09-09 (§10.3, printed p.20) [VA] NOTE: ''preferiblemente, hasta tres veces'' is a preference CEILING, not a floor; gate CR-020 encodes only <= 3, so zero washes passes - see STAGED R-12.', verified_at=now() where id='9dab3160-7120-42b2-bce2-3b094aaf5fb1' and verification_status not in ('verified_against_standard','corrected');

-- sampling_mode  (§10, printed p.20-22)
update public.fields set verification_status='verified_against_standard', verification_quote='10.4 Muestreo directo El muestreo directo proporciona el mínimo riesgo de contaminación, garantizando al mismo tiempo una muestra representativa. Sin embargo, no se debería emplear con botellas que contengan conservantes. | 10.5 Muestreo indirecto mediante el uso de un frasco de muestreo | 10.6 Muestreo a través de hielo | 10.7 Muestreo de las películas o capas superficiales | 10.8 Muestreo mediante incrementos — printed p.20-22', verification_note='md-verified 2026-09-09 (§10, printed p.20-22) [VA] NOTE: quote joins the 10.4 text with the 10.5-10.8 headings the enum mirrors 1:1.', verified_at=now() where id='fd8539e9-285d-4ed1-a800-ce229bccf5a3' and verification_status not in ('verified_against_standard','corrected');

-- increment_total_time  (§10.8, printed p.22)
update public.fields set verification_status='verified_against_standard', verification_quote='simples. Para la muestra que se considera como simple y discreta, el tiempo total para todos los incrementos que se adopten deberían ser tal que no se esperaría ningún cambio en la composición del río. Si esto no se conoce, el tiempo para todos los incrementos que se adopten debería ser menor que 5 min. — printed p.22', verification_note='md-verified 2026-09-09 (§10.8, printed p.22) [VA] NOTE: printed ''deberia ser menor que 5 min'' - gate CR-021 (< 5) matches the printed strict inequality.', verified_at=now() where id='f563e4f1-5778-49f9-8618-ef6f853488c9' and verification_status not in ('verified_against_standard','corrected');

-- field_preservative_added  (§10.9, printed p.22)
update public.fields set verification_status='verified_against_standard', verification_quote='Se requiere la preservación de ciertos tipos de muestra en el campo. Algunas botellas de muestra ya deberían contener conservantes y otras deberían tener el conservante añadido en el momento | del muestreo, por ejemplo, cuando se toman muestras para el oxígeno disuelto. Se debería consultar ISO 5667-3 y las normas analíticas específicas para obtener información sobre la conservación de las muestras. Seguir cualquier instrucción específica del fabricante para añadir los conservantes y tener — printed p.22', verification_note='md-verified 2026-09-09 (§10.9, printed p.22) [VA]', verified_at=now() where id='94d9543f-eec2-41d1-9f00-76d3c6996acb' and verification_status not in ('verified_against_standard','corrected');

-- sample_labelled  (§10.10, printed p.22)
update public.fields set verification_status='verified_against_standard', verification_quote='Las muestras se deberían etiquetar como se especifica en 12.2 en el momento de la recogida y antes | de ir al sitio de muestreo siguiente. Para obtener más detalles sobre problemas de trazabilidad, cadena de custodia, sistemas de calidad y registro, ver 11.3.2 y 12.3. — printed p.22', verification_note='md-verified 2026-09-09 (§10.10, printed p.22) [VA]', verified_at=now() where id='34533e99-4545-4003-82a3-fec8c76e3268' and verification_status not in ('verified_against_standard','corrected');

-- risk_factors_excluded  (§10.1, printed p.19)
update public.fields set verification_status='verified_against_standard', verification_quote='En la medida de lo posible, excluir los factores de riesgo que podrían causar contaminación o algún efecto en la muestra e indicar estos factores en el formulario de muestreo. Entre los factores que podrían dar lugar a un efecto perjudicial sobre la muestra, se incluyen: a) factores ambientales: — printed p.19', verification_note='md-verified 2026-09-09 (§10.1, printed p.19) [VA]', verified_at=now() where id='d4ed8f7a-35dd-41c6-bf70-2d4359cff984' and verification_status not in ('verified_against_standard','corrected');

-- preservation_per_iso5667_3  (§11.1, printed p.22)
update public.fields set verification_status='verified_against_standard', verification_quote='La estabilidad e integridad de las muestras es de suma importancia. Las muestras se deberían estabilizar o conservar de acuerdo con las disposiciones de ISO 5667-3 y las normas analíticas apropiadas. | Todos los pasos de la conservación se deberían registrar en el informe, además de medir y registrar la temperatura de almacenamiento. — printed p.22', verification_note='md-verified 2026-09-09 (§11.1, printed p.22) [VA]', verified_at=now() where id='daf237cf-25bc-4564-9d4a-ada051347aae' and verification_status not in ('verified_against_standard','corrected');

-- on_site_filtration_done  (§11.1, printed p.22)
update public.fields set verification_status='verified_against_standard', verification_quote='Para algunas aplicaciones, el muestreo se refiere a una evaluación de especies solubles (por ejemplo, metales traza en agua de río). Si este es el caso, entonces es necesario separar el material disuelto del particulado tan pronto como sea posible después del muestreo (es decir, preferiblemente en el sitio de muestreo antes de su traslado al laboratorio). Esto minimiza los cambios en la composición, que de lo | o análisis posterior del laboratorio. Varias técnicas están disponibles, pero la más conveniente para su uso en el campo (es decir, fuera del laboratorio) es la filtración, cuyos detalles se presentan en ISO 5667-3. — printed p.22', verification_note='md-verified 2026-09-09 (§11.1, printed p.22) [VA]', verified_at=now() where id='15b25ce6-191a-41db-a87c-92409ae96cb5' and verification_status not in ('verified_against_standard','corrected');

-- storage_temperature  (§11.1, printed p.22)
update public.fields set verification_status='verified_against_standard', verification_quote='Todos los pasos de la conservación se deberían registrar en el informe, además de medir y registrar la temperatura de almacenamiento. — printed p.22', verification_note='md-verified 2026-09-09 (§11.1, printed p.22) [VA]', verified_at=now() where id='c2cfcfe3-4c33-4cb1-80f7-b63e661bbc26' and verification_status not in ('verified_against_standard','corrected');

-- sample_traceability_maintained  (§11.3.1, printed p.23)
update public.fields set verification_status='verified_against_standard', verification_quote='El operador de muestreo tiene una responsabilidad respecto a la seguridad y la trazabilidad de las muestras, submuestras y los documentos de registro de muestras en su cuidado. | El operador de muestreo debería comprobar que las muestras, submuestras, etiquetas, documentos de registro de muestras, etc., estén en buen estado y depositados en el lugar designado. Si se pierde, daña o quiebra algún recipiente durante el transporte, esto se debería registrar por el operador de muestreo en el formulario de registro de muestras. Si un mensajero está involucrado, entonces éste — printed p.23', verification_note='md-verified 2026-09-09 (§11.3.1, printed p.23) [VA]', verified_at=now() where id='233ce0dd-2c3f-4414-bd2e-389f4cfc77d1' and verification_status not in ('verified_against_standard','corrected');

-- legal_purpose_sample  (§11.3.2, printed p.23)
update public.fields set verification_status='verified_against_standard', verification_quote='Los reglamentos que se deberían seguir si las muestras se van a utilizar para propósitos legales, pueden ser mucho más complicados dependiendo del sistema legal que funciona en una jurisdicción en particular. | ATENCION - Cabe destacar la existencia, en algunos países de legislación local, con la que todas las personas implicadas en cualquier etapa de la toma de muestras, almacenamiento o entrega de muestras, o en la documentación asociada, debería — printed p.23', verification_note='md-verified 2026-09-09 (§11.3.2, printed p.23) [VA] NOTE: the printed modality is ''Los reglamentos que se deberian seguir'' (SHOULD); the field description says ''shall'' - see STAGED R-11.', verified_at=now() where id='0e57a443-5a2d-4067-b203-f044615e5112' and verification_status not in ('verified_against_standard','corrected');

-- contamination_avoidance_instructions  (§12.1, printed p.23)
update public.fields set verification_status='verified_against_standard', verification_quote='Se deberían proporcionar instrucciones específicas escritas al personal de muestreo sobre los protocolos a seguir para evitar la contaminación en aguas superficiales de muestreo. Se debería fomentar que el personal de muestreo documente cualquier desviación de los riesgos previstos para facilitar la interpretación de los resultados. — printed p.23', verification_note='md-verified 2026-09-09 (§12.1, printed p.23) [VA]', verified_at=now() where id='c3ef8e9f-a821-40fb-9749-ad429622bd6c' and verification_status not in ('verified_against_standard','corrected');

-- disposable_gloves_used  (§12.1, printed p.23)
update public.fields set verification_status='verified_against_standard', verification_quote='Los operadores de muestreo deberían utilizar guantes desechables durante todo el procedimiento de muestreo, para protegerse del contacto con la muestra y para prevenir que la muestra se contamine. Es importante evitar la contaminación cruzada de un lugar de muestreo a otro mediante la manipulación de ropa y equipamiento de protección de muestreo, de tal manera que se evite la contaminación cruzada. — printed p.23', verification_note='md-verified 2026-09-09 (§12.1, printed p.23) [VA]', verified_at=now() where id='012db388-9209-4639-b18c-25ef634765e4' and verification_status not in ('verified_against_standard','corrected');

-- sample_identified_unambiguously  (§12.2, printed p.24)
update public.fields set verification_status='verified_against_standard', verification_quote='Los recipientes de las muestras se deberían identificar claramente y sin ambigüedad, de modo que los resultados analíticos posteriores se puedan interpretar debidamente. Todos los detalles pertinentes para la identificación de la muestra se deberían registrar en una etiqueta pegada al envase de la muestra. — printed p.24', verification_note='md-verified 2026-09-09 (§12.2, printed p.24) [VA]', verified_at=now() where id='92dc9f7f-bfd2-4af3-8962-985d703ef800' and verification_status not in ('verified_against_standard','corrected');

-- qc_qa_per_iso5667_14  (§12.3, printed p.24)
update public.fields set verification_status='verified_against_standard', verification_quote='El control de calidad mide el requerimiento de calidad de un proceso y utiliza técnicas para corregir cualquier desviación de un proceso. Consultar ISO 5667-14 para detalles completos de dichas técnicas, para su uso en el muestreo de ríos. Estas técnicas incluyen la capacitación, la calibración del equipamiento, el registro de datos y el uso de blancos para detectar la contaminación cruzada. Se recomienda encarecidamente el uso de medidas de control de calidad adecuadas para optimizar la calidad de los resultados. — printed p.24', verification_note='md-verified 2026-09-09 (§12.3, printed p.24) [VA]', verified_at=now() where id='b4637879-fdbf-40aa-8a81-b4d172667e62' and verification_status not in ('verified_against_standard','corrected');

-- analytical_report_complete  (§13.1, printed p.24)
update public.fields set verification_status='verified_against_standard', verification_quote='El formulario detallado del informe del muestreo depende de los objetivos de éste. Todas las condiciones que pueden influenciar los resultados analíticos, se deberían tener en cuenta. Los asuntos que se podrían considerar para su inclusión son: — printed p.24', verification_note='md-verified 2026-09-09 (§13.1, printed p.24) [VA]', verified_at=now() where id='c6ddb694-266e-47a9-afaa-b02028f85306' and verification_status not in ('verified_against_standard','corrected');

-- report_item  (§13.1, printed p.24-25)
update public.fields set verification_status='verified_against_standard', verification_quote='podrían considerar para su inclusión son: a) nombre del río o curso de agua; b) punto de muestreo (es decir, la posición de muestreo en la sección transversal en el sitio de muestreo); | p) cualquier nota del recolector de la muestra que pueda haber influenciado potencialmente la muestra (por ejemplo, el polvo en el aire, desove de los peces, tráfico cercano); y q) referencia a esta parte de NCh-ISO 5667 (NCh-ISO 5667/6:2015). — printed p.24-25', verification_note='md-verified 2026-09-09 (§13.1, printed p.24-25) [VA] NOTE: the printed lead-in is ''Los asuntos que se podrian considerar para su inclusion son'' - a permissive, non-exhaustive list; encoded as a closed single-select enum and as a required completeness flag - see STAGED R-7/R-8.', verified_at=now() where id='2dfc3e21-86ea-44ac-bb78-d4fc6d4e498f' and verification_status not in ('verified_against_standard','corrected');

-- protocol_change_history_kept  (§13.2, printed p.25)
update public.fields set verification_status='verified_against_standard', verification_quote='Se debería guardar un historial de los cambios a los procedimientos y protocolos de muestreo para permitir que una persona que examina los datos, tenga la oportunidad de evaluar los impactos de los cambios en los procedimientos, tanto en el campo como en el laboratorio, sobre la serie de observaciones recogidas. Los cambios en el laboratorio, como los límites de detección y la precisión, generalmente son registrados, pero los cambios en los métodos de muestreo, los puntos de muestreo y el personal, deberían ser parte del registro. En ocasiones, esto se aplica a una estación específica, — printed p.25', verification_note='md-verified 2026-09-09 (§13.2, printed p.25) [VA]', verified_at=now() where id='2cc09441-767e-4944-8a70-a6848f59cd76' and verification_status not in ('verified_against_standard','corrected');

-- quality_management_system  (§14, printed p.26)
update public.fields set verification_status='verified_against_standard', verification_quote='En muchas partes del mundo, se han desarrollado o adoptado, y aplicado sistemas de gestión de calidad al muestreo de la calidad del agua. Estos sistemas intentan controlar los factores que afectan la calidad de los datos finales producidos. | NOTA Un ejemplo es ISO/IEC 17025. | Los sistemas en sí no especifican la calidad de los datos, que se define por la razón de su producción. | Estos requerimientos se deberían especificar por el usuario de los datos antes del muestreo. — printed p.26', verification_note='md-verified 2026-09-09 (§14, printed p.26) [VA]', verified_at=now() where id='0cc66d07-944c-441f-94c9-14743789083d' and verification_status not in ('verified_against_standard','corrected');

-- safety_assessment_done  (§15, printed p.26)
update public.fields set verification_status='verified_against_standard', verification_quote='Para cada evento de muestreo, siempre se deberían evaluar problemas de seguridad personales y, si es adecuado, llevar a cabo una evaluación de riesgos en el sitio. Se debería proporcionar equipamiento — printed p.26', verification_note='md-verified 2026-09-09 (§15, printed p.26) [VA]', verified_at=now() where id='4bb801cb-4760-4981-87ad-34923d2fe30d' and verification_status not in ('verified_against_standard','corrected');

-- ppe_provided  (§15, printed p.26)
update public.fields set verification_status='verified_against_standard', verification_quote='es adecuado, llevar a cabo una evaluación de riesgos en el sitio. Se debería proporcionar equipamiento de protección personal, como equipo de flotación, una varilla de profundidad y ropa de alta visibilidad, | para garantizar la seguridad. | No se deberían utilizar vadeadores, ya que presentan un riesgo de seguridad. — printed p.26', verification_note='md-verified 2026-09-09 (§15, printed p.26) [VA]', verified_at=now() where id='ccaae552-bbf0-4c7e-8e1f-4fc2c0effaac' and verification_status not in ('verified_against_standard','corrected');

-- risk_assessment_outcome  (§15, printed p.26)
update public.fields set verification_status='verified_against_standard', verification_quote='Se debería realizar una evaluación de riesgos en todos los casos, en relación a si existe el riesgo suficiente de que: — no se debería intentar realizar el muestreo en absoluto; — el muestreo sólo se debería intentar si el operador de muestreo se ha sujetado con seguridad a un punto de anclaje adecuado; y — el muestreo sólo se debería intentar si una segunda persona está presente con un arnés y cuerdas para asegurar a la persona encargada de tomar la muestra a la orilla, para su seguridad, en este caso, la segunda persona se debería mantener alejada de cualquier peligro. — printed p.26', verification_note='md-verified 2026-09-09 (§15, printed p.26) [VA]', verified_at=now() where id='62384ede-3a98-4e0c-acc7-824604964d8b' and verification_status not in ('verified_against_standard','corrected');

-- unsafe_condition_present  (§15, printed p.26-27)
update public.fields set verification_status='verified_against_standard', verification_quote='ADVERTENCIA - Si se considera que las condiciones para realizar el muestreo no son seguras, no intentar realizar el muestreo. Entre tales condiciones se incluyen: — hielo, si hay dudas acerca del espesor o la capacidad de soporte de carga del hielo, o la falta de una formación adecuada para muestrear en y a través del hielo; | — condiciones del río, como lluvia intensa o nieve, haciendo que las condiciones del terreno sean peligrosas o un riesgo significativo de deslizamiento; y — en áreas remotas donde las comunicaciones se podrían ver comprometidas o no ser posibles, por ejemplo, sin señal de teléfono. — printed p.26-27', verification_note='md-verified 2026-09-09 (§15, printed p.26-27) [VA]', verified_at=now() where id='e44ca59f-dc25-48f7-aad7-6ff68c0a3cf9' and verification_status not in ('verified_against_standard','corrected');

-- l  (Anexo A, printed p.28)
update public.fields set verification_status='verified_against_standard', verification_quote='La distancia en metros, l, para la mezcla completa, dentro del 1% de homogeneidad completa, se puede calcular aproximadamente con Ecuación (A.1) siguiente (publicado originalmente en ISO 555-2[2]: — printed p.28', verification_note='md-verified 2026-09-09 (Anexo A, printed p.28) [VA]', verified_at=now() where id='b33c24f3-c597-4c39-9b32-7d63e659efdb' and verification_status not in ('verified_against_standard','corrected');

-- b  (Anexo A, printed p.28)
update public.fields set verification_status='verified_against_standard', verification_quote='en que: b = ancho promedio del tramo, expresado en metros (m); — printed p.28', verification_note='md-verified 2026-09-09 (Anexo A, printed p.28) [VA]', verified_at=now() where id='d3e1e28c-7505-4d76-85d8-205ae9e60990' and verification_status not in ('verified_against_standard','corrected');

-- c  (Anexo A, printed p.28)
update public.fields set verification_status='verified_against_standard', verification_quote='c = coeficiente de Chézy para el tramo (15 < c < 50); | EJEMPLO Considerar dos cursos de agua, ambos de 5 m de ancho y 1 m de profundidad, pero con valores extremos del coeficiente de Chézy; uno de 15 (fondo muy irregular, es decir, el curso de agua es muy rápido y turbulento) y el otro de 50 (fondo muy liso, es decir, un curso de agua muy tranquilo, de movimiento lento). Cuando se calcula según — printed p.28', verification_note='md-verified 2026-09-09 (Anexo A, printed p.28) [VA] NOTE: ''(15 < c < 50)'' is a STRICT two-sided bound; no gate encodes it and the point value is an SR-2 engineer selection - see STAGED R-13.', verified_at=now() where id='8faf0f0e-ece4-4e88-8cc9-2d586fe87e5a' and verification_status not in ('verified_against_standard','corrected');

-- g  (Anexo A, printed p.28)
update public.fields set verification_status='verified_against_standard', verification_quote='g = aceleración debido a la gravedad, expresada en metros por segundo al cuadrado (m/s2); — printed p.28', verification_note='md-verified 2026-09-09 (Anexo A, printed p.28) [VA] NOTE: only the symbol definition and unit are printed; the numeric value 9,81 m/s2 is NOT printed anywhere in this document.', verified_at=now() where id='7aee7b04-7082-497b-9f8b-d013783a5ed1' and verification_status not in ('verified_against_standard','corrected');

-- d  (Anexo A, printed p.28)
update public.fields set verification_status='verified_against_standard', verification_quote='d = profundidad media del tramo, expresada en metros (m). — printed p.28', verification_note='md-verified 2026-09-09 (Anexo A, printed p.28) [VA]', verified_at=now() where id='5736cc48-a8f5-48bf-8b26-c282ff7289b2' and verification_status not in ('verified_against_standard','corrected');

-- ---- Section B: equations (1 of 2 rows; Eq. A.1 is deliberately NOT verified - see header + STAGED R-1) ----
-- Eq. 2  sampling_depth_below_surface = preferred_subsurface_depth  (§7.3, printed p.15)
update public.equations set verification_status='verified_against_standard', verification_quote='Los recipientes de recolección deberían ser sumergidos en el flujo principal del cauce del agua y en la zona homogénea, de manera tal de recoger una muestra de agua sin incluir la película superficial o remolinos de agua. Siempre que sea posible, las muestras de agua se deberían recoger a alrededor de 30 cm por debajo de la superficie, o de otra manera, a media altura entre el lecho y la superficie. — printed p.15', verification_note='md-verified 2026-09-09 (§7.3, printed p.15) [VA] NOTE: Eq.2 is a PASS-THROUGH identity (sampling_depth_below_surface = preferred_subsurface_depth), not a computation; the quote verifies the 30 cm recommendation both symbols carry, not a calculation. The duplicate-symbol consolidation is staged as R-10.', verified_at=now() where id='7e099928-b002-453a-9109-e620c5091337' and verification_status <> 'verified_against_standard';
